// --------------------------------------------------- the container's own view

/// The two streams of `av.mp4`, as a correct MP4 demuxer must report them.
fn av_mp4_streams() -> Vec<Stream> {
    let mut video = Stream::new(0, MediaType::Video, Rational::new(1, 12800));
    video.id = Some(1);
    video.start_time = Timestamp::new(0);
    // Ticks in the stream's own base, which is what the container states and
    // what `duration_ts=25600` prints. Deriving it from 2 000 000 µs happened
    // to work here only because 2 s is a whole number of 1/12800 ticks.
    video.duration_ts = Some(25_600);
    video.r_frame_rate = Rational::new(25, 1);
    video.avg_frame_rate = Rational::new(25, 1);
    video.frame_count = Some(50);
    video.disposition = Disposition::DEFAULT;
    video.metadata = vec![
        ("language".to_owned(), "und".to_owned()),
        ("handler_name".to_owned(), "VideoHandler".to_owned()),
        ("encoder".to_owned(), "Lavc62.28.100 libx264".to_owned()),
    ];
    video.params = CodecParameters::video().with_codec(CodecId::H264);
    video.params.codec_tag = Some(*b"avc1");
    video.params.bit_rate = Some(270_332);
    video.params.profile = Some(Profile {
        value: 100,
        name: "High",
    });
    video.params.level = Some(Level(13));
    video.params.extradata = Some(vec![0; 46]);
    if let Some(v) = video.params.video.as_mut() {
        v.width = 320;
        v.height = 240;
        v.coded_width = 320;
        v.coded_height = 240;
        v.has_b_frames = 2;
        v.sample_aspect_ratio = Rational::ONE;
        v.frame_rate = Rational::new(25, 1);
        v.format = vaco_pixfmt::PixFmt::from_name("yuv420p").ok();
        v.color.chroma_location = vaco_color::ChromaLocation::Left;
        v.field_order = vaco_codec_core::FieldOrder::Progressive;
        // Both from the bitstream parser, through `ParserProvider`. `avcC`
        // declares a four-byte length prefix, which is `is_avc=true
        // nal_length_size=4`; the SPS's `bit_depth_luma` is 8.
        v.bits_per_raw_sample = Some(8);
        v.nal_length_size = Some(4);
    }

    let mut audio = Stream::new(1, MediaType::Audio, Rational::new(1, 44100));
    audio.id = Some(2);
    audio.start_time = Timestamp::new(0);
    audio.duration_ts = Some(88_200);
    audio.frame_count = Some(88);
    audio.disposition = Disposition::DEFAULT;
    audio.metadata = vec![
        ("language".to_owned(), "und".to_owned()),
        ("handler_name".to_owned(), "SoundHandler".to_owned()),
    ];
    audio.params = CodecParameters::audio().with_codec(CodecId::Aac);
    audio.params.codec_tag = Some(*b"mp4a");
    audio.params.bit_rate = Some(69_655);
    audio.params.profile = Some(Profile {
        value: 1,
        name: "LC",
    });
    audio.params.extradata = Some(vec![0; 5]);
    if let Some(a) = audio.params.audio.as_mut() {
        a.sample_rate = 44100;
        a.format = vaco_sampfmt::SampleFmt::from_name("fltp").ok();
        a.layout = Some(ChannelLayout::MONO);
    }

    vec![video, audio]
}

fn av_mp4_format() -> FormatInfo<'static> {
    FormatInfo {
        filename: "av.mp4",
        format_name: "mov,mp4,m4a,3gp,3g2,mj2",
        format_long_name: "QuickTime / MOV",
        probe_score: 100,
        size: Some(88_307),
        nb_programs: 0,
        nb_stream_groups: 0,
    }
}

const METADATA: &[(&str, &str)] = &[
    ("major_brand", "isom"),
    ("minor_version", "512"),
    ("compatible_brands", "isomiso2avc1mp41"),
    ("encoder", "Lavf62.12.100"),
];

/// `ffprobe -v quiet -of default -show_streams -select_streams v rot.mov`,
/// the `[SIDE_DATA]` block only.
///
/// `rot.mov` is `av.mp4`'s content muxed to MOV with the video `tkhd` matrix
/// byte-patched to a 90-degree rotation
/// (`[0, 65536, 0, -65536, 0, 0, 7864320, 0, 1073741824]`). Column widths are
/// load-bearing and were read with `od -c`, not by eye.
const SIDE_DATA_DEFAULT: &str = "\
[SIDE_DATA]
side_data_type=Display Matrix
displaymatrix=
00000000:            0       65536           0
00000001:       -65536           0           0
00000002:      7864320           0  1073741824

rotation=-90
[/SIDE_DATA]
";

/// `ffprobe -v quiet -of default -show_programs ts.ts`, the program's own
/// fields only — the nested `[STREAM]` sections are `stream_fields`, already
/// covered above.
///
/// There is no `pmt_version` line, and `-show_optional_fields always` does not
/// add one. Plan 18 §1.1 says `vaco-probe` prints it; measurement says the
/// section has five fields and that is not one of them.
const PROGRAM_DEFAULT_HEAD: &str = "\
[PROGRAM]
program_id=1
program_num=1
nb_streams=2
pmt_pid=4096
pcr_pid=256
";

// ------------------------------------------------------------------ rendering

fn render(spec: &str, f: impl FnOnce(&mut Emit<'_, Vec<u8>>)) -> String {
    let w = writers::make(spec).expect("writer spec");
    let mut tf = TextFormat::new(w, Vec::new(), FormatOpts::default());
    tf.open(SectionId::ROOT).expect("root");
    {
        let mut e = Emit::new(&mut tf, OptionalFields::Auto);
        f(&mut e);
    }
    tf.close().expect("root");
    String::from_utf8(tf.finish().expect("finish")).expect("utf8")
}

fn streams(spec: &str) -> String {
    render(spec, |e| {
        e.tf().open(SectionId::STREAMS).expect("streams");
        for s in &av_mp4_streams() {
            show::stream(e, s, true, show::Counts::NONE).expect("stream");
        }
        e.tf().close().expect("streams");
    })
}

fn format(spec: &str) -> String {
    let meta: Vec<(String, String)> = METADATA
        .iter()
        .map(|(k, v)| ((*k).to_owned(), (*v).to_owned()))
        .collect();
    render(spec, |e| {
        show::format(e, &av_mp4_format(), &av_mp4_streams(), Some(2.0), &meta).expect("format");
    })
}

/// Every line where ours and the reference's differ, as `(theirs, ours)`.
///
/// `ours` is `None` for a line we do not emit at all.
fn divergences(reference: &str, ours: &str) -> Vec<(String, Option<String>)> {
    let mine: Vec<&str> = ours.lines().collect();
    let mut out = Vec::new();
    for line in reference.lines() {
        if mine.contains(&line) {
            continue;
        }
        let key = line.split_once('=').map(|(k, _)| k);
        let same_key = key.and_then(|k| {
            mine.iter()
                .find(|m| m.split_once('=').map(|(mk, _)| mk) == Some(k))
        });
        out.push((line.to_owned(), same_key.map(|s| (*s).to_owned())));
    }
    out
}

// ---------------------------------------------------------------------- tests

/// The `format` section is byte-identical in every writer.
///
/// Not "almost": these three assertions compare whole documents including
/// trailing newlines, and `format` has no field this build cannot fill.
#[test]
fn format_is_byte_identical_in_default_ini_and_xml() {
    assert_eq!(format("default"), FORMAT_DEFAULT);
    assert_eq!(format("ini"), FORMAT_INI);
    assert_eq!(format("xml"), FORMAT_XML);
}

/// Everything the `stream` section gets right, which is most of it.
///
/// Asserted as an exact list rather than a count, so a field that starts
/// diverging is named in the failure.
#[test]
fn stream_lines_that_match_the_reference() {
    let ours = streams("default");
    let mine: Vec<&str> = ours.lines().collect();
    let matched: Vec<&str> = STREAMS_DEFAULT
        .lines()
        .filter(|l| mine.contains(l))
        .collect();
    // All 116 reference lines, over two streams. It was 113 until the parser
    // seam landed; the three that were missing were `is_avc`,
    // `nal_length_size` and the video `bits_per_raw_sample`.
    assert_eq!(
        matched.len(),
        STREAMS_DEFAULT.lines().count(),
        "unexpected divergence:\n{:#?}",
        divergences(STREAMS_DEFAULT, &ours)
    );
}

/// The lines we do **not** reproduce — and there are now none.
///
/// This list has been shrinking rather than growing, and each closure failed
/// this assertion first, which is what it is for: a divergence disappearing is
/// a change to observable output and gets reviewed like any other.
///
/// * `codec_long_name` — `vaco-codec-core` said "H.264 / AVC / MPEG-4 AVC"
///   where the reference appends " / MPEG-4 part 10". Closed upstream.
/// * `is_avc`, `nal_length_size` — the h264 decoder's private options.
///   `CodecParameters` had nowhere to put them; `VideoParameters` now carries
///   `nal_length_size` and the H.264 parser fills it from `avcC`.
/// * `bits_per_raw_sample` — lived on `AudioParameters` only, so a *video*
///   stream could not report the 8 the reference prints. It is on
///   `VideoParameters` too now, and that is the half that is printed.
#[test]
fn the_known_stream_divergences_are_exactly_these() {
    let ours = streams("default");
    let found: Vec<(String, Option<String>)> = divergences(STREAMS_DEFAULT, &ours);
    let names: Vec<&str> = found
        .iter()
        .map(|(theirs, _)| theirs.split_once('=').map_or(theirs.as_str(), |(k, _)| k))
        .collect();
    let empty: [&str; 0] = [];
    assert_eq!(names, empty, "divergence set moved:\n{found:#?}");
}

/// A per-writer check that the field set is a property of the *fields*, not of
/// one writer.
#[test]
fn the_same_six_fields_diverge_in_every_writer() {
    for spec in ["default", "flat", "compact", "ini", "xml", "json"] {
        let ours = streams(spec);
        // `is_avc` is emitted by every writer now, and only for the H.264
        // stream — the AAC stream beside it must not grow one.
        assert_eq!(ours.matches("is_avc").count(), 1, "{spec}");
        assert!(ours.contains("h264"), "{spec}");
        assert!(ours.contains("mp4a.40.2"), "{spec}: mime_codec_string");
    }
}

/// The int-vs-string table, checked through the writer that spells it.
///
/// This is the assertion the crate exists for: `json` quotes a string field and
/// not an integer one, and the reference's choices are reproduced exactly.
#[test]
fn json_quoting_matches_the_reference_field_for_field() {
    let ours = streams("json");
    for unquoted in [
        "\"index\": 0",
        "\"width\": 320",
        "\"height\": 240",
        "\"coded_width\": 320",
        "\"coded_height\": 240",
        "\"has_b_frames\": 2",
        "\"level\": 13",
        "\"start_pts\": 0",
        "\"duration_ts\": 25600",
        "\"extradata_size\": 46",
        "\"channels\": 1",
        "\"bits_per_sample\": 0",
        "\"initial_padding\": 0",
    ] {
        assert!(ours.contains(unquoted), "{unquoted} should be an integer");
    }
    for quoted in [
        "\"codec_name\": \"h264\"",
        "\"sample_aspect_ratio\": \"1:1\"",
        "\"display_aspect_ratio\": \"4:3\"",
        "\"id\": \"0x1\"",
        "\"time_base\": \"1/12800\"",
        "\"start_time\": \"0.000000\"",
        "\"duration\": \"2.000000\"",
        "\"bit_rate\": \"270332\"",
        "\"nb_frames\": \"50\"",
        "\"sample_rate\": \"44100\"",
        "\"channel_layout\": \"mono\"",
    ] {
        assert!(ours.contains(quoted), "{quoted} should be a string");
    }
    // `json` omits unavailable optional fields at the default policy, which is
    // why none of these appear even though `default` prints them as `N/A`.
    for omitted in [
        "max_bit_rate",
        "nb_read_frames",
        "nb_read_packets",
        "color_range",
    ] {
        assert!(
            !ours.contains(omitted),
            "{omitted} should be omitted by json"
        );
    }
}

/// Both streams, byte for byte, with **nothing** removed from either side.
///
/// This used to drop three lines from both sides — `is_avc`,
/// `nal_length_size` and `bits_per_raw_sample`, all three missing *inputs*
/// rather than formatting choices — and asserted 113 of 116. All three now
/// arrive, so the filter is gone and the assertion is the whole document.
#[test]
fn the_streams_are_byte_identical_apart_from_the_known_gaps() {
    assert_eq!(streams("default"), STREAMS_DEFAULT);
}

/// The stream `[SIDE_DATA]` block, byte for byte.
///
/// This is the one that would have gone wrong silently: the `displaymatrix`
/// value's three rows are `%08x:` plus three right-aligned **12**-column
/// integers, which is 37 characters after the colon. The obvious reading —
/// `": %11d %11d %11d"` — gives 36 and is wrong on every line, but only by a
/// space, so nothing short of a byte comparison catches it.
#[test]
fn the_display_matrix_side_data_block_is_byte_identical() {
    let mut s = Stream::new(0, MediaType::Video, Rational::new(1, 12800));
    s.side_data
        .push(vaco_format_core::StreamSideData::DisplayMatrix([
            0,
            65536,
            0,
            -65536,
            0,
            0,
            7_864_320,
            0,
            1 << 30,
        ]));
    let out = render("default", |e| {
        show::side_data(e, &s).expect("side data");
    });
    assert_eq!(out, SIDE_DATA_DEFAULT);
}

/// A stream with no side data opens no list at all — the reference emits
/// neither `[SIDE_DATA]` nor an empty `side_data_list`.
#[test]
fn a_stream_without_side_data_opens_no_list() {
    let s = Stream::new(0, MediaType::Video, Rational::new(1, 12800));
    assert_eq!(
        render("default", |e| show::side_data(e, &s).expect("none")),
        ""
    );
}

/// The `[PROGRAM]` header fields, in the reference's order.
#[test]
fn the_program_section_prints_five_fields_in_order() {
    let mut p = vaco_format_core::Program::new(1);
    p.program_num = Some(1);
    p.pmt_pid = Some(4096);
    p.pcr_pid = Some(256);
    p.pmt_version = Some(0);
    p.stream_indices = vec![0, 1];
    let streams = av_mp4_streams();
    let out = render("default", |e| {
        show::program(e, &p, &streams, false, &|_| show::Counts::NONE).expect("program");
    });
    let head = out
        .lines()
        .take_while(|l| *l != "[STREAM]")
        .fold(String::new(), |mut acc, l| {
            acc.push_str(l);
            acc.push('\n');
            acc
        });
    assert_eq!(head, PROGRAM_DEFAULT_HEAD);
}

/// `id` is printed only by a container that declares `SHOW_IDS`.
///
/// Measured: the same H.264 track reports `id=0x1` out of MP4 and `id=N/A` out
/// of Matroska, which declares no `SHOW_IDS`. The `Stream::id` field is set in
/// both cases — Matroska's `TrackNumber` is what `-map 0:#1` resolves against —
/// so the suppression has to happen at the printer.
#[test]
fn the_id_field_follows_show_ids() {
    let streams = av_mp4_streams();
    let with = render("default", |e| {
        for s in &streams {
            show::stream(e, s, true, show::Counts::NONE).expect("stream");
        }
    });
    let without = render("default", |e| {
        for s in &streams {
            show::stream(e, s, false, show::Counts::NONE).expect("stream");
        }
    });
    assert!(with.contains("\nid=0x1\n"), "{with}");
    assert!(without.contains("\nid=N/A\n"), "{without}");
    assert!(!without.contains("id=0x1"));
}
